package dev.arabicgames.phone;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=35)
public class CaptionNoiseTest {
 @Test public void dashboardVariantsCollapseToOneDialogueInsteadOfRepeatedModelRequests(){String line="Then we can take the time to make a plan that's not fuckin'\nstupid.";var c=RuntimeEnvironment.getApplication();assertEquals(line,CaptionNoise.clean(c,"Red Dead Redemption 2\nXBOX Insider Hub\nSAME\nPASS\nQ\n)\n"+line,"GTA 6"));assertEquals(line,CaptionNoise.clean(c,"Red Dead Redemption 2\nXBOX Insider Hub\nPASS\n"+line,"GTA6"));}
 @Test public void preservesDialogueNamesAndRemovesOnlyObservedCredits(){var c=RuntimeEnvironment.getApplication();assertEquals("I'm Jason.\nLucia.",CaptionNoise.clean(c,"I'm Jason.\nLucia.","GTA6"));assertEquals("I still can't believe I shacked up with a car thief.",CaptionNoise.clean(c,"Wn shoemaken\nNeiL WaLKeR\nI still can't believe I shacked up with a car thief.","GTA6"));assertEquals("",CaptionNoise.clean(c,"GRESS\n4ER\nINE\nIAL CLUB\nTINGS\nPHOTO MoDE SELECT AB","GTA6"));}
 @Test public void anOlderCachedDictionaryCannotOverrideNewBundledCorrections()throws Exception{var c=RuntimeEnvironment.getApplication();java.io.File cache=new java.io.File(c.getFilesDir(),"community-reviewed.json");String old="{\"format\":\"arabic-games-reviewed-v1\",\"source\":\"en\",\"target\":\"ar\",\"revision\":0,\"entries\":[]}";java.nio.file.Files.write(cache.toPath(),old.getBytes(java.nio.charset.StandardCharsets.UTF_8));org.robolectric.util.ReflectionHelpers.setStaticField(CommunityCorrections.class,"initialized",false);assertEquals("الآن أطفئ المحرك وانخفض.",CommunityCorrections.find(c,"GTA 6","Now kill the engine, get down."));cache.delete();org.robolectric.util.ReflectionHelpers.setStaticField(CommunityCorrections.class,"initialized",false);}
 @Test public void gameAliasesStayScopedAndReviewedCorrectionsFixMeaning(){var c=RuntimeEnvironment.getApplication();assertTrue(GameNames.same("gta6","Grand Theft Auto VI"));assertFalse(GameNames.same("RDR2","GTA6"));assertEquals("الآن أطفئ المحرك وانخفض.",CommunityCorrections.find(c,"GTA 6","Now kill the engine, get down."));assertNull(CommunityCorrections.find(c,"RDR2","Now kill the engine, get down."));assertEquals("This is a game, pass the ball.",CaptionNoise.clean(c,"This is a game, pass the ball.","GTA6"));}
}
